    [426] = {
        achievementId = 426,
        name = "Warglaives of Azzinoth",
        category = "Collections",
        sourceType = "Achievement",
        source = "Warglaives of Azzinoth",
        acquisition = "Difficulty: Hard - Obtain both rare legendary swords on the same eligible character across weekly raid loot opportunities.\n\n1. Choose ONE character who can equip both original Warglaive of Azzinoth swords at the same time: Warrior, Rogue, Death Knight, Monk or Demon Hunter. Select a dual-wielding specialization where necessary. Merely learning an appearance or looting the blades on an ineligible class does not award this feat.\n\n2. Enter original Black Temple through the wall breach at 71.0, 46.5 in Outland Shadowmoon Valley. Clear through the Illidari Council, speak to Akama and defeat Illidan, including both Flames of Azzinoth during his airborne phase.\n\n3. Loot Illidan for the MAIN-HAND blade (32837) and OFF-HAND blade (32838). They are separate random drops; two copies of one hand do not make a set. Keep the first blade and return on the same character after each weekly reset for the other.\n\n4. Equip both blades simultaneously on that character to earn Warglaives of Azzinoth. One blade on each of two alts does not satisfy the feat.\n\n5. Optional Demon Hunter appearance: after this feat is complete, defeat Illidan during the separate Black Temple TIMEWALKING event for I'll Hold These For You Until You Get Out and use its Arsenal reward. That event is not needed for the original two-blade feat, and the Timewalking kill need not be on a Demon Hunter.",
        stepCount = 5,
        waypoints = {
            { mapID = 104, x = 0.71, y = 0.465, step = 2, label = "Original Black Temple entrance" },
            {
                mapID = 346,
                x = 0.5277000000000001,
                y = 0.7045999999999999,
                step = 3,
                label = "Illidan - main-hand and off-hand blade drops",
                mapName = "Black Temple - Temple Summit",
            },
        },
        tips = "The original blades are classified as one-handed swords. The special Demon Hunter transmog unlock and this equipment feat are distinct achievements.",
        wowheadUrl = "https://www.wowhead.com/achievement=426",
        sourceURL = "https://www.wowhead.com/achievement=426#comments",
        difficultyReason = "Obtain both rare legendary swords on the same eligible character across weekly raid loot opportunities.",
        difficulty = "hard",
    },
    [587] = {
        achievementId = 587,
        name = "Stormy Assassin",
        category = "PvP",
        sourceType = "Achievement",
        source = "Stormy Assassin",
        acquisition = "Difficulty: Medium - Play the battleground objectives or complete a personal capture or buffed kill; a few matches may be needed.\n\n1. Track all FOUR counters and queue for regular Eye of the Storm. In one match, earn five honorable kills at EACH tower. Twenty kills in the middle do not replace these four location-specific groups.\n\n2. At Mage Tower in the northwest, help kill enemy players within the tower's capture area until that criterion reaches five. Fight where the capture bar appears, rather than pulling targets far down the bridge.\n\n3. Rotate to Draenei Ruins in the northeast and earn its five honorable kills. Check the tracked counter after kills; the reply correction stresses that the ENEMY'S position near the base matters too.\n\n4. Move to Fel Reaver Ruins in the southwest and fill its five-kill counter. Keep helping your team defend or contest the base so enemies keep fighting inside the scoring area.\n\n5. Finish five honorable kills at Blood Elf Tower in the southeast. The towers can be done in any order; rotate toward active fights and revisit whichever counter is incomplete before the match ends.\n\n6. Check all four counters in that SAME battle. Killing blows are unnecessary, but staying close enough for honorable-kill credit is important. Older comments describe broader credit; use the visible counters to confirm what actually credited on your attempt.",
