            {
                mapID = 103,
                x = 0.313,
                y = 0.479,
                step = 4,
                label = "Nearby wall - control knockback without resetting Velen",
                mapName = "The Exodar",
            },
        },
        tips = "The 2025 Retail report describes moving Velen out of his healing pool and killing returning Vigilant Defenders. Fight duration varies; a solo kill is not promised.",
        sources = {
            "https://www.wowhead.com/achievement=618#comments:id=3303778",
