    [694] = {
        achievementId = 694,
        name = "Serpentshrine Cavern",
        category = "Raids",
        sourceType = "Achievement",
        source = "Serpentshrine Cavern",
        acquisition = "Difficulty: Easy - Clear the named legacy dungeon or raid and finish its scripted encounters; combat is straightforward at current max level.\n\n1. Dive down Coilfang Reservoir's central pipe in Serpent Lake and surface in the cavern. Enter the central RAID portal, not one of the neighboring five-player dungeons.\n\n2. Follow the platforms and bridges to Lady Vashj. Other bosses are useful for pets and appearances but are not the named kill requirement. The Lurker Below must be fished from his Strange Pool if you also want that encounter.\n\n3. Defeat Lady Vashj. If she reaches her shield phase, kill Tainted Elementals, loot their Tainted Cores promptly and use them on the four shield generators. A high-level character may kill her before this phase.",
