    [726] = {
        achievementId = 726,
        name = "Mr. Pinchy's Magical Crawdad Box",
        category = "Collections",
        sourceType = "Achievement",
        source = "Mr. Pinchy's Magical Crawdad Box",
        acquisition = "Difficulty: Hard - Fish up rare Mr. Pinchy and use his limited wishes until the Magical Crawdad Box reward appears.\n\n1. Use a character of at least level 23 with Fishing and flight access to Terokkar's elevated lakes. Outland Fishing can be learned from Juno Dufrain in Zangarmarsh (78.5, 63.0). You do not need old unsplit Fishing 375 to attempt the catch.\n\n2. Fly to Blackwind Lake in Skettis (around 67.8, 79.6), Lake Ere'Noru beside Allerian Stronghold (59, 59) or Lake Jorune (45.8, 40). Search specifically for HIGHLAND MIXED SCHOOLS. Fish out each school and move along the shoreline; ordinary open-water casts are the wrong farm.\n\n3. Fully loot your catches until you obtain Mr. Pinchy (27388). Watch for a binding confirmation so you do not lose the rare item by immediately recasting. Furious Crawdad is an ordinary cooking fish, not Mr. Pinchy or the pet box.\n\n4. With bag space available, right-click Mr. Pinchy to spend a wish. It has three charges and may award a creature, a buff, a gift or Magical Crawdad Box. The achievement requires the BOX from a wish, not merely catching Mr. Pinchy.\n\n5. If the box does not appear, keep the item and wait FOUR HOURS for the next wish. Copies on the same character share that cooldown. Use the remaining wishes; if all three fail, fish up another Mr. Pinchy and continue.\n\n6. When a wish awards Magical Crawdad Box (27445), check the achievement and use the box to learn the pet. A bought caged Magical Crawdad can fill your Pet Journal but does not replace this achievement's personal box objective. Neither stage has a guaranteed cast or wish count.",
        stepCount = 6,
        waypoints = {
            { mapID = 102, x = 0.785, y = 0.63, step = 1, label = "Juno Dufrain - Outland Fishing trainer" },
            {
                mapID = 108,
                x = 0.6779999999999999,
                y = 0.7959999999999999,
                step = 2,
                label = "Blackwind Lake - Highland Mixed School search circuit",
            },
            { mapID = 108, x = 0.59, y = 0.59, step = 2, label = "Lake Ere'Noru - elevated lake alternative" },
            { mapID = 108, x = 0.45799999999999996, y = 0.4, step = 2, label = "Lake Jorune - elevated lake alternative" },
        },
        wowheadUrl = "https://www.wowhead.com/achievement=726",
        sourceURL = "https://www.wowhead.com/achievement=726#comments",
        difficultyReason = "Fish up rare Mr. Pinchy and use his limited wishes until the Magical Crawdad Box reward appears.",
        difficulty = "hard",
    },
    [733] = {
        achievementId = 733,
        name = "Professional Outland Master",
        category = "Professions",
        sourceType = "Achievement",
        source = "Professional Outland Master",
        acquisition = "Difficulty: Medium - Raise the required Outland profession skill bars with expansion-specific training, materials or gathering.\n\n1. Open this achievement's progress and check the OUTLAND skill bars already credited. The objective is 75 skill in one Outland primary profession.\n\n2. Train the OUTLAND tier separately. Hellfire's Honor Hold and Thrallmar have trainers for most professions; ask a guard for your profession's location. For Inscription, use Recorder Lidio on Shattrath's Aldor Rise (36.2, 44.6) or Scribe Lanloer on Scryer's Tier (56.6, 74.6). For Engineering, use Technician Mihila on Aldor Rise (37.6, 31.6) or Engineer Sinbei on Scryer's Tier (43.6, 65.0). Choose the Shattrath side that is friendly to you. Cooking, Fishing and Archaeology do not replace a primary profession.\n\n3. Skinning option: train with Jelena Nightsky at Honor Hold (54.4, 63.2) or Moorutu at Thrallmar (56.2, 38.6). In OUTLAND Nagrand, kill and fully loot the clefthoofs and talbuks in the grasslands between Garadar, Halaa and Oshu'gun, then skin their corpses. Continue until OUTLAND Skinning is 75. A corpse with somebody's loot still on it cannot be skinned; move through the herds rather than waiting on one spawn.\n\n4. Herbalism / Mining options: train with Rorelien (53.6, 65.8) or Ruak Stronghorn (52.2, 36.2) for Herbalism, and Hurnak Grimmord (56.6, 63.8) or Krugosh (55.4, 37.6) for Mining. Enable the appropriate minimap tracking. Circle Hellfire's open ground for Felweed and Dreaming Glory and its cliffs for Fel Iron. If the easy nodes stop giving skill, move to Nagrand or Blade's Edge for higher Outland herbs and Adamantite. Gather the nodes yourself until the relevant bar is 75; buying herbs/ore does not level gathering.\n\n5. Crafting option: select OUTLAND recipes and inspect their actual skill color before making a batch. Engineering starts with Fel Iron Bolts, Fel Iron Casings and Elemental Blasting Powder, which feed later bombs/grenades. Tailoring uses Netherweave Cloth for bolts, bags and Netherweave armor. Leatherworking uses Knothide Leather for armor kits and Draenic/Felscale armor. Keep useful intermediate materials instead of selling everything between stages; return to the trainer when the current recipe turns green or grey.\n\n6. For the other crafting bars, use Alchemy's Outland elixirs/potions, Blacksmithing's Fel Iron armor and later Adamantite recipes, Enchanting's Arcane Dust / Planar Essence enchants, Jewelcrafting's Outland gem cuts and Adamantite jewelry, or Inscription's Ethereal Ink / Darkflame Ink recipes. Check the Unlearned recipe's source and required skill before buying reagents: some later recipes are vendor, reputation or dungeon drops. A recipe grey below 75 cannot finish the bar, even if its materials came from Outland.\n\n7. Raise each required Outland bar to 75 and recheck its criterion. For Outland Master of All the full list is Alchemy, Blacksmithing, Enchanting, Engineering, Herbalism, Inscription, Jewelcrafting, Leatherworking, Mining, Skinning and Tailoring. Use profession alts for that account-wide list instead of deleting a developed profession to rotate through eleven skills. If you only need one or two bars, follow the options for those chosen professions and skip the others.",
