    [877] = {
        achievementId = 877,
        name = "The Cake Is Not A Lie",
        category = "Professions",
        sourceType = "Achievement",
        source = "The Cake Is Not A Lie",
        acquisition = "Difficulty: Hard - Obtain the random cooking recipe from reward bags, then gather its ingredients and cook the cake.\n\n1. Search your Cooking recipes for Delicious Chocolate Cake before farming. If already learned, skip to gathering ingredients. The objective is to BAKE the cake, not merely learn the recipe or eat a bought cake.\n\n2. Complete The Rokk's cooking daily in Shattrath (61.6, 15.8) and open the Crate of Meat or Barrel of Fish until Recipe: Delicious Chocolate Cake drops. Northrend Dalaran's cooking daily Small Spice Bag is another source. These are random rewards, not guaranteed after a set number of days.\n\n3. Optional during the appropriate Timewalking week: buy those recipe-containing cooking reward bags from Cupri in Shattrath or Auzin in Northrend Dalaran with Timewarped Badges. Opening bought reward containers gives additional attempts; buying a finished cake does not.\n\n4. Learn the recipe and gather 8 Simple Flour, 8 Small Eggs, 4 Mild Spices, 4 Ice Cold Milk, 3 Mageroyal and 1 Flask of Port. Flour/spices come from cooking suppliers; milk/port from drink vendors. Buy the eggs and herb or gather them. Kylene in Shattrath's World's End Tavern sells the port.\n\n5. Stand beside a cooking fire and personally craft one Delicious Chocolate Cake. Check the achievement. Clear recipe filters if it does not appear; do not spend more days farming a recipe that is already in your Cooking book.",
        stepCount = 5,
        waypoints = {
            { mapID = 111, x = 0.616, y = 0.158, step = 2, label = "The Rokk - cooking daily reward bags" },
            {
                mapID = 125,
                x = 0.40299999999999997,
                y = 0.6609999999999999,
                step = 2,
                label = "Alliance: Katherine Lee - Northrend cooking daily",
            },
            { mapID = 125, x = 0.7, y = 0.389, step = 2, label = "Horde: Awilo Lon'gomba - Northrend cooking daily" },
            {
                mapID = 111,
                x = 0.545,
