                label = "Cupri - Burning Crusade Timewalking vendor when active",
            },
            { mapID = 125, x = 0.506, y = 0.45, step = 3, label = "Auzin - Northrend Timewalking vendor when active" },
            { mapID = 111, x = 0.735, y = 0.327, step = 4, label = "Kylene - World's End Tavern drink vendor" },
        },
        wowheadUrl = "https://www.wowhead.com/achievement=877",
        sourceURL = "https://www.wowhead.com/achievement=877#comments",
