    [882] = {
        source = "Attumen the Huntsman - original Karazhan raid, stables",
        category = "Dungeon and Raids",
        faction = "all",
        npcId = 16152,
        requirements = "An eligible character capable of clearing the original Karazhan raid encounter.",
        cost = "No purchase cost for the raid-drop route.",
        tips = "This is the original raid's weekly attempt, not the Legion dungeon's lockout. Different characters provide additional independent chances, not a guaranteed drop after a particular number of kills. The mapped instance floor is the original Karazhan floor. Obtain and learn the mount on this account. The feat may trigger when the reins are looted; its Feat of Strength category does not mean this mount has been removed.",
        waypoints = {
            { mapID = 42, x = 0.469, y = 0.748, step = 1, label = "Original Karazhan - ground-level raid entrance" },
