    [902] = {
        achievementId = 902,
        name = "Chief Exalted Officer",
        category = "Reputation",
        sourceType = "Achievement",
        source = "Chief Exalted Officer",
        acquisition = "Difficulty: Medium - Repeat quests, dungeon clears or item turn-ins until the required faction reaches Exalted.\n\n1. Go to Area 52 in Netherstorm and find Nether-Stalker Khay'ji (32.4, 64.2). Follow his A Heap of Ethereals quest until Another Heap of Ethereals is available.\n\n2. Kill Zaxxis ethereals in The Heap southwest of Area 52, around 30, 75. Loot Zaxxis Insignias; each stack of 10 can be handed in to Khay'ji for 250 base Consortium reputation. Circle the camps and return to town with your stacks.\n\n3. Repeat the insignia hand-ins all the way to Exalted. Optional: at Friendly or above, follow the Consortium's Ethereum Prison quest introduction from Commander Ameer at the Protectorate Watch Post (59.5, 32.3) before using the keys you find.\n\n4. For a daily dungeon alternative, set Mana-Tombs to HEROIC and clear its trash and bosses. Its reputation gains continue to Exalted. Normal Mana-Tombs has an earlier reputation cap and cannot replace the full Exalted route.\n\n5. Keep doing insignia turn-ins between Heroic resets until Exalted. Obsidian Warbeads are another reputation source, but spend them on Kurenai/Mag'har first if you still need those reputations. No special title is awarded by Chief Exalted Officer.",
        stepCount = 5,
