    [903] = {
        achievementId = 903,
        name = "Shattrath Divided",
        category = "Reputation",
        sourceType = "Achievement",
        source = "Shattrath Divided",
        acquisition = "Difficulty: Medium - Repeat quests, dungeon clears or item turn-ins until the required faction reaches Exalted.\n\n1. In Shattrath's Terrace of Light, complete Khadgar's City of Light introduction and choose the Aldor OR the Scryers. This achievement needs Exalted with one side; both sides are required only for Hero of Shattrath.\n\n2. For Aldor, hand Marks of Kil'jaeden to Adyen the Lightwarden on Aldor Rise until Honored; then use Marks of Sargeras. Fel Armaments handed to High Priestess Ishanah are an alternative. Shadow Labyrinth's demons and Shadowmoon Valley's Legion camps supply Aldor items.\n\n3. For Scryers, give Firewing Signets to Magistrix Fyalenn on Scryer's Tier until Honored; then use Sunfury Signets. Arcane Tomes handed to Voren'thal the Seer are an alternative. Botanica and Netherstorm's blood elf camps supply Scryer items.\n\n4. Do your chosen faction's Netherstorm/Shadowmoon quests and repeat the eligible hand-ins until Exalted. Higher-rank marks/signets and the armament/tome hand-ins remain useful after Honored. Bought tradable turn-in items work; compare prices rather than assuming old comment prices still apply.",
        stepCount = 4,
        waypoints = {
