    [905] = {
        achievementId = 905,
        name = "Old Man Barlowned",
        category = "Quests",
        sourceType = "Achievement",
        source = "Old Man Barlowned",
        acquisition = "Difficulty: Medium - Complete each required daily quest when it is offered; the rotation prevents finishing all objectives on demand.\n\n1. Learn Outland Fishing and visit Old Man Barlo beside Silmyr Lake north of Shattrath (38.7, 12.8 on the Terokkar map). Use a character eligible for his daily; recent Retail NPC information requires level 30. One of his five quests is offered each day.\n\n2. For Crocolisks in the City, fish in Stormwind's canals or Orgrimmar's city water until you catch the Baby Crocolisk. Return it to Barlo; a wild battle-pet capture does not replace the quest fish.\n\n3. For Bait Bandits, fish in Terokkar Forest's rivers for a Blackfin Darter. Ordinary open river water works; it is a quest fish, not the School of Darter achievement objective.\n\n4. For Felblood Fillet, fish in the fel waters of Hellfire Peninsula or Outland Shadowmoon Valley for a Monstrous Felblood Snapper.\n\n5. For Shrimpin' Ain't Easy, fish in Zangarmarsh for Bloated Barbed Gill Trout. OPEN each bloated fish to collect Giant Freshwater Shrimp until you have all 10.\n\n6. For The One That Got Away, fish in Outland Nagrand's lakes for the World's Largest Mudfish. Be patient and loot each cast; the quest item is separate from an ordinary Figluster's Mudfish.\n\n7. Turn in each of the five DIFFERENT quests to Barlo. Return after future daily resets for missing names. The random rotation can repeat; old realm-hopping advice is not a dependable replacement for waiting. Open the reward bags for extra recipes and, on Crocolisks in the City, possible crocolisk pets.",
        stepCount = 7,
        waypoints = {
            { mapID = 108, x = 0.387, y = 0.128, step = 1, label = "Old Man Barlo - daily quest giver" },
            { mapID = 84, x = 0.61, y = 0.65, step = 2, label = "Stormwind canals - Crocolisks in the City fishing area" },
