        acquisition = "Difficulty: Easy - Buy and equip the Gigantique bag from Haris Pilton for its ordinary vendor price.\n\n1. Bring 1,200 gold and go to Haris Pilton in the World's End Tavern in Shattrath's Lower City (75.5, 30.5).\n\n2. Buy the exact item \"Gigantique\" Bag (38082). Portable Hole, ordinary larger bags and profession/reagent bags do not substitute for it.\n\n3. Empty one of your character's ordinary equipped bag slots and equip the Gigantique bag there. Owning it in your backpack or using it as a bank bag does not meet the objective. Equipping binds it; do not plan to pass it around or obtain a full vendor refund afterwards.",
        stepCount = 3,
        waypoints = { { mapID = 111, x = 0.755, y = 0.305, step = 1, label = "Haris Pilton - World's End Tavern; 1,200-gold bag" } },
