    [1275] = {
        achievementId = 1275,
        name = "Bombs Away",
        category = "Quests",
        sourceType = "Achievement",
        source = "Bombs Away",
        acquisition = "Difficulty: Medium - Unlock the bombing quest or Netherwing races and complete the route with the required mechanics.\n\n1. Leave all groups: the achievement requires a SOLO attempt. Unlock Blackwind Landing through Yuula's Threat from Above in Shattrath and To Skettis. At Blackwind Landing, locate Sky Sergeant Doryn (64.6, 66.6 in Terokkar). Use a flying mount and put the supplied Skyguard Blasting Charges on an accessible action-bar key before attempting the timer.\n\n2. Track this achievement, then accept Fires Over Skettis. The timer starts on acceptance. Fly toward the Skettis tree platforms and roofs around Blackwind Lake; the targets are egg clusters on buildings, not birds on the ground.\n\n3. Bomb groups of Monstrous Kaliri Eggs until the quest counter reaches 20. Place the targeting circle over the eggs themselves; a well-placed bomb can hit several. Move toward your next roof during the bomb cooldown. Watch for attacking kaliri, and use Steady Flight if Skyriding makes aiming difficult.\n\n4. Finish the objective within 2 minutes 15 seconds and return promptly to Doryn to turn in. Recent Retail comments report credit when the final eggs are destroyed, but budgeting for the return also avoids relying on that behavior. If the attempt fails, abandon and reaccept before turning in; a completed daily cannot be repeated that day.",
        stepCount = 4,
        waypoints = {
            { mapID = 111, x = 0.64, y = 0.42, step = 1, label = "Yuula - Skyguard introduction" },
            { mapID = 108, x = 0.22, y = 0.12, step = 1, label = "Barrier Hills - introductory ogres" },
            { mapID = 108, x = 0.6459999999999999, y = 0.6659999999999999, step = 1, label = "Doryn - Fires Over Skettis" },
            { mapID = 108, x = 0.67, y = 0.77, step = 3, label = "Skettis - search rooftop egg clusters around the lake" },
            { mapID = 108, x = 0.6459999999999999, y = 0.6659999999999999, step = 4, label = "Doryn - return and turn in" },
        },
        wowheadUrl = "https://www.wowhead.com/achievement=1275",
        sourceURL = "https://www.wowhead.com/achievement=1275#comments",
        difficultyReason = "Unlock the bombing quest or Netherwing races and complete the route with the required mechanics.",
        difficulty = "medium",
    },
    [1276] = {
        achievementId = 1276,
        name = "Blade's Edge Bomberman",
        category = "Quests",
        sourceType = "Achievement",
        source = "Blade's Edge Bomberman",
        acquisition = "Difficulty: Hard - Finish the full bombing objective within its short timer while avoiding anti-air attacks.\n\n1. Leave all groups: the achievement requires a SOLO attempt. Unlock the Skyguard Outpost through Ogri'la's introductory crystal/flask quests and The Skyguard Outpost. Complete Vanderlip's introductory Bombing Run first; the achievement attempt uses the DAILY Bomb Them Again!, not that first bombing quest.\n\n2. At Sky Sergeant Vanderlip (27.6, 52.9), prepare your flying mount and bind Skyguard Bombs before accepting. Track the achievement. Accept Bomb Them Again! and fly immediately NORTH to Forge Camp: Wrath, around 33, 40. Skyriding can shorten the journeys; you can land while still mounted to aim each bomb, then launch toward the next pile.\n\n3. Destroy 15 Fel Cannonball Stacks. Aim at the small ammunition piles near the flak cannons, center the circle carefully, and line up your next target during every bomb cooldown. Stay inside the camp boundary so the bombs can be used. Current Retail replies say the old double-tap trick no longer works.\n\n4. Make your last targets the stacks nearest the southern exit, then return directly to Vanderlip and TURN IN within 2 minutes 15 seconds of accepting. Fast travel to/from the camp matters as much as aiming. If the timer fails, abandon and retry before completing the daily; after turn-in, wait for another daily reset.",
        stepCount = 4,
        waypoints = {
            { mapID = 105, x = 0.28800000000000003, y = 0.574, step = 1, label = "Ogri'la - introductory quests" },
            { mapID = 105, x = 0.276, y = 0.529, step = 2, label = "Vanderlip - accept timed DAILY" },
            { mapID = 105, x = 0.33, y = 0.4, step = 3, label = "Forge Camp: Wrath - bomb 15 ammunition stacks" },
            { mapID = 105, x = 0.276, y = 0.529, step = 4, label = "Vanderlip - timed turn-in" },
        },
        wowheadUrl = "https://www.wowhead.com/achievement=1276",
        sourceURL = "https://www.wowhead.com/achievement=1276#comments",
        difficultyReason = "Finish the full bombing objective within its short timer while avoiding anti-air attacks.",
        difficulty = "hard",
    },
    [1284] = {
        achievementId = 1284,
        name = "Outland Dungeonmaster",
        category = "Dungeons",
