    [1638] = {
        achievementId = 1638,
        name = "Skyshattered",
        category = "Quests",
        sourceType = "Achievement",
        source = "Skyshattered",
        acquisition = "Difficulty: Medium - Unlock the bombing quest or Netherwing races and complete the route with the required mechanics.\n\n1. Unlock the Netherwing base camp through Mordenai's introductory chain and reach HONORED with Netherwing. At the disguised Dragonmaw camp on Netherwing Ledge, take the racing introduction Earning Your Wings. These races do not start at a mainland flight master.\n\n2. Complete the Netherwing races in order: Murg 'Oldie' Muckjaw, Trope the Filth-Belcher, Corlok the Vet, Wing Commander Ichman, Wing Commander Mulverick, and finally Captain Skyshatter. Talk to each rider and let them start; the final race is not available immediately.\n\n3. Use a responsive flying mount, preferably Steady Flight, and follow the rider's actual turns. Stay close enough to keep the race active while flying above or offset from the stream of thrown attacks. Attacks can knock you back, but the old automatic-dismount behavior was removed. Recover your position and keep following unless the quest actually fails; watch the rider during pauses instead of flying far ahead.\n\n4. For Captain Skyshatter, learn his sharp turns and altitude changes on a practice attempt. Follow above/alongside him where possible and avoid cutting so far ahead that the race loses contact. After the successful flight, TURN IN the quest to claim Skyshattered; simply reaching the landing strip does not complete it.",
        stepCount = 4,
        waypoints = {
            { mapID = 104, x = 0.6, y = 0.59, step = 1, label = "Mordenai - Netherwing introductory chain" },
            {
                mapID = 104,
                x = 0.66,
                y = 0.8640000000000001,
                step = 1,
                label = "Dragonmaw base camp - Honored racing introduction",
            },
            { mapID = 104, x = 0.655, y = 0.853, step = 2, label = "Netherwing Ledge - Dragonmaw racing strip" },
            { mapID = 104, x = 0.655, y = 0.853, step = 4, label = "Racing strip - Captain Skyshatter and final turn-in" },
        },
        wowheadUrl = "https://www.wowhead.com/achievement=1638",
        sourceURL = "https://www.wowhead.com/achievement=1638#comments",
        difficultyReason = "Unlock the bombing quest or Netherwing races and complete the route with the required mechanics.",
        difficulty = "medium",
    },
    [1800] = {
        achievementId = 1800,
        name = "The Outland Gourmet",
        category = "Professions",
        sourceType = "Achievement",
        source = "The Outland Gourmet",
        acquisition = "Difficulty: Hard - Collect the full recipe list, including random daily-reward recipes, and personally cook all required dishes.\n\n1. Learn Outland Cooking in Shattrath and raise it to 75. Track the achievement's 25 dishes: YOU must cook each one. Buying cooked food or merely learning its recipe does not credit it. Sporeling Snack is no longer a criterion.\n\n2. Visit Kylene in the World's End Tavern (73.5, 32.7 in Shattrath). Learn and cook Fisherman's Feast from Huge Spotted Feltail, Hot Buttered Trout from Enormous Barbed Gill Trout, and Stewed Trout from Barbed Gill Trout. These are easily missed because they are trainer recipes rather than the usual recipe-vendor items.\n\n3. In Hellfire, complete Legassi's crashed-zeppelin quest chain (49.2, 74.8) for Recipe: Buzzard Bites, then cook it from Buzzard Meat. Buy Ravager Dog from Sid Limbardi at Honor Hold or Cookie One-Eye at Thrallmar, according to faction, and cook it from Ravager Flesh.\n\n4. In Zangarmarsh, obtain Feltail Delight and Blackened Trout from your faction's vendors: Doba at Orebor, or Zurai/Gambarinka at Swamprat Post/Zabra'jin. Buy Blackened Sporefish from Juno Dufrain at Cenarion Refuge. Mycah in Sporeggar sells Clam Bar for a Glowcap. Cook all four using Spotted Feltail, Barbed Gill Trout, Zangarian Sporefish and Jaggal Clam Meat respectively.\n\n5. In Nagrand, visit Uriku in Telaar (Alliance) or Nula the Butcher in Garadar (Horde). Buy and cook Grilled Mudfish, Poached Bluefish, Roasted Clefthoof and Talbuk Steak. Bring Figluster's Mudfish, Icefin Bluefish, Clefthoof Meat and Talbuk Venison.\n\n6. In Blade's Edge, buy Crunchy Serpent and Mok'Nathal Shortribs from Sassa Weldwell at Toshley's Station (Alliance), or Xerintha Ravenoak in Evergrove. Cook them from Serpent Flesh and Raptor Ribs. Horde can also obtain these recipes through Mok'Nathal Treats at Mok'Nathal Village.\n\n7. In Terokkar, buy Blackened Basilisk and Warp Burger from Supply Officer Mills at Allerian Stronghold (Alliance) or Innkeeper Grilka at Stonebreaker Hold (Horde). Buy Golden Fish Sticks and Spicy Crawdad from Innkeeper Biribi at Allerian or Rungor at Stonebreaker. Cook them using Chunk o' Basilisk, Warped Flesh, Golden Darter and Furious Crawdad.\n\n8. Do The Rokk's cooking dailies in Shattrath (61.7, 16.2), choosing the reward crates for missing recipes. The six crate recipes are Broiled Bloodfin, Skullfish Soup, Kibler's Bits, Spicy Hot Talbuk, Stormchops and Delicious Chocolate Cake. Relevant Timewalking recipe bags are another source when offered; random rewards can require repeated days.\n\n9. Cook the final six dishes with Bloodfin Catfish, Crescent-Tail Skullfish, Buzzard Meat, Talbuk Venison and Lightning Eel for their respective recipes. Chocolate Cake also needs 8 Simple Flour, 8 Small Eggs, 4 Ice Cold Milk, 4 Mild Spices, 3 Mageroyal and 1 Flask of Port. Use the tracked missing criteria to finish only the recipes you still need.",
        stepCount = 9,
        waypoints = {
            { mapID = 111, x = 0.735, y = 0.327, step = 2, label = "Kylene - three special cooking recipes" },
            { mapID = 100, x = 0.49200000000000005, y = 0.748, step = 3, label = "Legassi - Buzzard Bites quest chain" },
            { mapID = 100, x = 0.5429999999999999, y = 0.636, step = 3, label = "Sid Limbardi - Alliance Ravager Dog" },
