            { mapID = 105, x = 0.76, y = 0.603, step = 6, label = "Mok'Nathal Village - Horde recipe quests" },
            { mapID = 108, x = 0.557, y = 0.532, step = 7, label = "Allerian Stronghold - Alliance four-recipe stop" },
            { mapID = 108, x = 0.488, y = 0.455, step = 7, label = "Stonebreaker Hold - Horde four-recipe stop" },
            { mapID = 111, x = 0.617, y = 0.162, step = 8, label = "The Rokk - random daily recipe crates" },
        },
        wowheadUrl = "https://www.wowhead.com/achievement=1800",
        sourceURL = "https://www.wowhead.com/achievement=1800#comments",
