    [4908] = {
        achievementId = 4908,
        name = "Ghostlands Quests",
        category = "Quests",
        sourceType = "Achievement",
        source = "Ghostlands Quests",
        faction = "Horde",
        difficulty = "medium",
        difficultyReason = "Complete several connected quest chapters, including their prerequisite hand-ins.",
        acquisition = "Difficulty: Medium - Complete several connected quest chapters, including their prerequisite hand-ins.\n\n1. Enable Trivial Quests on the minimap and track this achievement's CURRENT named chapters. Old comments' numeric quest totals predate storyline tracking. Turn in each branch's final quest and take its follow-up before leaving the hub. Use the original Ghostlands phase, not Midnight's rebuilt Quel'Thalas. As with the legacy Zul'Aman entrance, use the available Zidormi/earlier-Quel'Thalas access at Thalassian Pass when the modern landscape is active.\n\n2. Begin Tranquillien's investigations and finish the village's supply, undead and sanctum quests. Follow the road and Farstrider Enclave leads as they unlock; a completed Tranquillien reputation bar does not by itself finish the story chapters.\n\n3. For Farstrider Enclave, also visit Geranis Whitemorn on the lake's small island NORTH of the Enclave and complete his chain through Vanquishing Aquantion. His Tranquillien affiliation does not make these quests optional for the Enclave chapter.\n\n4. Complete the Windrunner/Deatholme prerequisites, including the Lady's Necklace lead where offered, then finish the Dar'Khan Drathir assault and final turn-in. Use the original quest phase; simply killing later-expansion enemies with similar names cannot award this chain.\n\n5. Check the remaining named chapters, return to their own hub and finish their hand-ins. A quest marker can be inside a building, on an object or just over the adjoining zone border. Unrelated dungeon quests, repeatable reputation turn-ins and an old total such as 60/60 do not substitute for the current story criteria.",
        stepCount = 5,
        waypoints = {
            { mapID = 95, x = 0.46, y = 0.32, step = 2, label = "Original Tranquillien - settlement quests" },
            { mapID = 95, x = 0.72, y = 0.32, step = 2, label = "Farstrider Enclave" },
            { mapID = 95, x = 0.72, y = 0.19, step = 3, label = "Lake island - Geranis Whitemorn branch" },
            { mapID = 95, x = 0.33, y = 0.67, step = 4, label = "Windrunner area - late story leads" },
            { mapID = 95, x = 0.33, y = 0.8, step = 4, label = "Deatholme - Dar'Khan finale" },
        },
        sources = {
            "https://www.wowhead.com/achievement=4908#comments:id=2134058",
            "https://www.wowhead.com/achievement=4908#comments:id=3198271",
        },
        reviewedAt = "2026-11-10",
        wowheadUrl = "https://www.wowhead.com/achievement=4908",
        sourceURL = "https://www.wowhead.com/achievement=4908#comments",
    },
    [4926] = {
        achievementId = 4926,
        name = "Bloodmyst Isle Quests",
        category = "Quests",
        sourceType = "Achievement",
        source = "Bloodmyst Isle Quests",
        faction = "Alliance",
        difficulty = "medium",
        difficultyReason = "Complete several connected quest chapters, including their prerequisite hand-ins.",
        acquisition = "Difficulty: Medium - Complete several connected quest chapters, including their prerequisite hand-ins.\n\n1. Enable Trivial Quests on the minimap and track this achievement's CURRENT named chapters. Old comments' numeric quest totals predate storyline tracking. Turn in each branch's final quest and take its follow-up before leaving the hub. Begin at Blood Watch and follow its Triumvirate quests. If a required Bloodcurse lead is missing, return to Admiral Odesyus in southern Azuremyst rather than searching only Bloodmyst.\n\n2. Finish the three separate Triumvirate branches from Boros, Kuros and Aesom. Talk to Boros even if he displays the repeatable Irradiated Crystal Shards marker; he can also have ordinary story quests behind that repeatable interaction.\n\n3. Complete Galaen's Fate and the Loreth'Aran ruins storyline, then the Bloodcurse chain. Check Messenger Hermesius at Blood Watch and Odesyus's The Bloodcurse Legacy lead on Azuremyst if the Bloodcurse chapter never opened.\n\n4. Continue Vindicator's Rest's defensive assault and The Unwritten Prophecy finale. Loot relevant quest starters, including Cruelfin's pendant/Tzerak's armor plate when they open unfinished branches. An old sixty/sixty-five quest list is not the current eight-chapter checklist.\n\n5. Check the remaining named chapters, return to their own hub and finish their hand-ins. A quest marker can be inside a building, on an object or just over the adjoining zone border. Unrelated dungeon quests, repeatable reputation turn-ins and an old total such as 60/60 do not substitute for the current story criteria.",
        stepCount = 5,
        waypoints = {
            { mapID = 106, x = 0.55, y = 0.55, step = 2, label = "Blood Watch - three Triumvirate branches" },
            { mapID = 106, x = 0.61, y = 0.44, step = 3, label = "Loreth'Aran - ruins story" },
            { mapID = 97, x = 0.47, y = 0.7, step = 3, label = "Odesyus' Landing - Bloodcurse prerequisite" },
            { mapID = 106, x = 0.31, y = 0.47, step = 4, label = "Vindicator's Rest - final defensive campaign" },
        },
        sources = {
            "https://www.wowhead.com/achievement=4926#comments:id=1190521",
            "https://www.wowhead.com/achievement=4926#comments:id=5758660",
        },
