        sourceURL = "https://www.wowhead.com/achievement=4926#comments",
    },
    [6587] = {
        achievementId = 6587,
        name = "Outland Safari",
        source = "Outland Safari",
        sourceType = "Achievement",
        difficulty = "hard",
        difficultyReason = "Complete a large species checklist with some limited or sparse spawns.",
        acquisition = "Difficulty: Hard - Complete a large species checklist with some limited or sparse spawns.\n\n1. Unlock pet trapping and track this Safari. You need the exact listed species, not a particular color or quality. Catching a rare is optional; capture any available quality before waiting for an upgrade.\n\n2. Work through the missing species zone by zone. Use each map's labelled search areas and the species' own guide where available. Lower a chosen wild pet below 35%, trap it, then win the full encounter. Inspect backline names too; only one opponent can be captured per battle.\n\n3. Use original Outland, reached through the Outland portal, rather than Draenor. Include the distinct species in Blade's Edge, Netherstorm, Shadowmoon Valley, Terokkar, Zangarmarsh and Nagrand; inspect backline opponents instead of looking only for primary green paws.\n\n4. Checklist: Adder; Brown Marmot; Clefthoof Runt; Fledgling Nether Ray; Mouse; Prairie Dog; Rat; Scalded Basilisk Hatchling; Skittering Cavern Crawler; Small Frog; Sporeling Sprout; Stripe-Tailed Scorpid; Toad; Ash Viper; Cat; Flayer Youngling; Fel Flame; Nether Roach; Rabbit; Rock Viper; Scorpid; Skunk; Snake; Squirrel; Tainted Cockroach; Warpstalker Hatchling.\n\n5. Check every criterion before leaving a region. For an unexpectedly missing entry, verify the exact species name and a completed capture. Do not release a valuable owned pet just because an old launch-bug comment suggested doing so. Return during a required season or weather window rather than treating those species as permanently unobtainable.",
        stepCount = 5,
        waypoints = {},
        areaMaps = { 101 },
        sources = {},
        wowheadUrl = "https://www.wowhead.com/achievement=6587",
        sourceURL = "https://www.wowhead.com/achievement=6587#comments",
        reviewedAt = "2026-11-13",
    },
    [6604] = {
        achievementId = 6604,
        name = "Taming Outland",
        source = "Taming Outland",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "A sequential account unlock and a team of trained battle pets are required.",
        acquisition = "Difficulty: Medium - A sequential account unlock and a team of trained battle pets are required.\n\n1. Start with Audrey Burnhep in Stormwind (Alliance) or Varzok in Orgrimmar (Horde). Complete the introductory healing, leveling and capture lessons, then accept each next tamer quest after winning. The unlock order is your home continent, Outland, Northrend, Cataclysm, then Pandaria. A trainer with no battle dialogue usually means an earlier quest or capital return is unfinished.\n\n2. Defeat Nicki Tinytech at 64.4,49.2. Bring Elemental attacks against all three mechanicals attacks to counter this team. Heal between battles and use rare-quality, appropriately leveled pets; your character's combat level does not improve pet attacks. Accept or complete the matching tamer quest before moving on.\n\n3. Defeat Ras'an at 17.2,50.6. Bring Undead, Magic and Dragonkin attacks to counter this team. Heal between battles and use rare-quality, appropriately leveled pets; your character's combat level does not improve pet attacks. Accept or complete the matching tamer quest before moving on.\n\n4. Defeat Narrok at 61,49.4. Bring Beast, Mechanical and Magic attacks to counter this team. Heal between battles and use rare-quality, appropriately leveled pets; your character's combat level does not improve pet attacks. Accept or complete the matching tamer quest before moving on.\n\n5. Defeat Morulu the Elder at 59.4,69.8. Bring Flying attacks against all three aquatics attacks to counter this team. Heal between battles and use rare-quality, appropriately leveled pets; your character's combat level does not improve pet attacks. Accept or complete the matching tamer quest before moving on.\n\n6. Defeat Bloodknight Antari at 31,41.4. Bring Aquatic, Dragonkin and Humanoid attacks to counter this team. Heal between battles and use rare-quality, appropriately leveled pets; your character's combat level does not improve pet attacks. Accept or complete the matching tamer quest before moving on.\n\n7. Turn in the continent assignment, defeat its grand master and accept the return to the capital. The grand-master introduction is distinct from the later repeatable daily. In Uldum, use Zidormi's earlier phase if needed; in the Vale use the earlier Pandaria phase for Aki, and look inside the Kota Peak cave for Yon. Check the achievement's individual trainer ticks before repeating battles.",
        stepCount = 7,
        waypoints = {
            { mapID = 84, x = 0.6940000000000001, y = 0.244, step = 1, label = "Audrey Burnhep - Alliance pet training" },
            { mapID = 85, x = 0.526, y = 0.593, step = 1, label = "Varzok - Horde pet training" },
            { mapID = 100, x = 0.644, y = 0.49200000000000005, step = 2, label = "Nicki Tinytech" },
            { mapID = 102, x = 0.172, y = 0.506, step = 3, label = "Ras'an" },
            { mapID = 107, x = 0.61, y = 0.494, step = 4, label = "Narrok" },
            { mapID = 111, x = 0.594, y = 0.698, step = 5, label = "Morulu the Elder" },
            { mapID = 104, x = 0.31, y = 0.414, step = 6, label = "Bloodknight Antari" },
        },
        sources = { "https://www.wowhead.com/achievement=6604#comments:id=1727467" },
        wowheadUrl = "https://www.wowhead.com/achievement=6604",
        sourceURL = "https://www.wowhead.com/achievement=6604#comments",
        reviewedAt = "2026-11-13",
    },
    [6614] = {
        achievementId = 6614,
        name = "Outland Tamer",
        source = "Outland Tamer",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Capture one wild pet in every listed zone.",
        acquisition = "Difficulty: Medium - Capture one wild pet in every listed zone.\n\n1. Prepare a capture team, unlock Trap and track this achievement. Visit the original continent named here; Outland Nagrand and Shadowmoon Valley are different zones from their Draenor counterparts.\n\n2. Capture one paw-marked wild pet in EACH of these zones: Hellfire Peninsula, Zangarmarsh, Terokkar Forest, Nagrand, Blade's Edge Mountains, Netherstorm and Shadowmoon Valley. Reduce its health below 35%, trap it and finish the battle successfully. Any capturable species and quality can satisfy that zone.\n\n3. Check the zone criterion before traveling onward. A purchased cage and merely winning without a capture do not replace a zone capture. If an invasion or destroyed phase has no suitable spawns, use that zone's Zidormi option to access its earlier Retail phase.",
        stepCount = 3,
        waypoints = {},
