    [8293] = {
        achievementId = 8293,
        name = "Raiding with Leashes II: Attunement Edition",
        source = "Raiding with Leashes II: Attunement Edition",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Ten random raid pets; tradeable cages also satisfy the collection.",
        acquisition = "Difficulty: Medium - Ten random raid pets; tradeable cages also satisfy the collection.\n\n1. Check the ten named species. You may buy and learn their cages instead of personally looting each raid. The old Burning Crusade raid attunement quest chains are not required to enter these raids in Retail.\n\n2. Enter original Karazhan through the ground-level front door. Kill Moroes to open Barnes's Opera; the Big Bad Wolf version drops Lil' Bad Wolf. Other Opera variants cannot drop that pet, so use another character or weekly reset if needed. The Curator drops Menagerie Custodian, Terestian Illhoof drops Fiendish Imp and Prince Malchezaar drops Netherspace Abyssal.\n\n3. Dive through Coilfang Reservoir's central pipe in Zangarmarsh and take the central Serpentshrine Cavern raid portal. Hydross the Unstable drops Tainted Waveling, Morogrim Tidewalker drops Tideskipper and Lady Vashj drops Coilfang Stalker. Clear the encounter requirements and use the bridge/control devices to reach Vashj.\n\n4. Fly to the large central Tempest Keep fortress in Netherstorm and enter The Eye. Al'ar drops Phoenix Hawk Hatchling, Void Reaver drops Pocket Reaver and High Astromancer Solarian drops Lesser Voidcaller. The smaller satellite dungeons have different loot.\n\n5. Loot and learn each pet or its cage, repeat only missing bosses on fresh eligible lockouts, and check the ten criteria. Tito's Basket is the achievement reward; do not farm it from a raid boss. The Legion Return to Karazhan dungeon does not replace original Karazhan.",
        stepCount = 5,
        waypoints = {
            {
                mapID = 42,
                x = 0.47,
                y = 0.7490000000000001,
                step = 2,
                label = "Original Karazhan - ground-level raid entrance",
            },
            { mapID = 102, x = 0.504, y = 0.409, step = 3, label = "Coilfang Reservoir - swim down the central pipe" },
            { mapID = 109, x = 0.735, y = 0.637, step = 4, label = "Tempest Keep - The Eye" },
        },
        sources = { "https://www.wowhead.com/achievement=8293#comments:id=1834244" },
        wowheadUrl = "https://www.wowhead.com/achievement=8293",
        sourceURL = "https://www.wowhead.com/achievement=8293#comments",
        reviewedAt = "2026-11-13",
    },
    [11706] = {
        achievementId = 11706,
        name = "The Original",
        category = "Collections",
        sourceType = "Achievement",
        source = "The Original",
        acquisition = "Difficulty: Medium - Earn 12 Marks of Honor and learn an ordinary legacy armor ensemble; no historical Arena rating is required.\n\n1. Use a character with an original Burning Crusade class armor set and collect 12 Marks of Honor. These are the item currency from PvP rewards, not the Honor points on the currency tab. No original season rating or title is required.\n\n2. Visit Kezzik the Striker inside Area 52's PvP-vendor building in Netherstorm (33.0, 64.2). Buy the Gladiator ARMOR Ensemble for your class. A weapon Arsenal does not finish the armor-set achievement.\n\n3. Use the Ensemble from your bags to permanently learn the complete set. If you already own most appearances, compare the price of the individual missing pieces before buying the ensemble; the full eight-piece individual purchase costs more than 12 Marks.\n\n4. Check the achievement after learning the set. For individual refundable purchases, wait for the refund timer to expire or permanently bind the items before expecting credit. Do not return them for a refund and assume the appearance remains collected.",
        stepCount = 4,
        waypoints = { { mapID = 109, x = 0.33, y = 0.642, step = 2, label = "Kezzik the Striker - Gladiator armor Ensemble" } },
        tips = "Monks, Death Knights, Demon Hunters and Evokers have no original Burning Crusade class tier; use an eligible original class to collect its class set.",
        sources = { "https://www.wowhead.com/achievement=11706#comments:id=2477596" },
        wowheadUrl = "https://www.wowhead.com/achievement=11706",
        sourceURL = "https://www.wowhead.com/achievement=11706#comments",
        difficultyReason = "Earn 12 Marks of Honor and learn an ordinary legacy armor ensemble; no historical Arena rating is required.",
        difficulty = "medium",
    },
    [11746] = {
        achievementId = 11746,
        name = "Outlandish Style",
        category = "Collections",
        sourceType = "Achievement",
        source = "Outlandish Style",
        acquisition = "Difficulty: Hard - Collect a complete class appearance set through random weekly raid drops and the relevant token exchanges.\n\n1. Open Collections > Appearances > Sets and select a complete Tier 4 appearance set for an original Burning Crusade class. Pin down its missing slots before farming; five tier pieces alone may leave required matching boots, belt or bracers unfinished.\n\n2. In original Karazhan, defeat The Curator for gloves and Prince Malchezaar for the helm. Follow the Opera and Chess events to reach the Prince; the Legion dungeon does not replace this raid.\n\n3. In Gruul's Lair, kill High King Maulgar for shoulders and Gruul for legs. Kill Magtheridon in his separate Hellfire Citadel raid for the chest token.\n\n4. Use eligible class tokens to create the armor, choosing the appropriate loot specialization. Where a token offers a choice, collect the PvE appearance, not its alternative PvP reward. A modern class with no original tier set cannot create that old class's tier pieces for itself.\n\n5. For every remaining slot in the SETS tab, inspect its specific appearance source and farm or craft that item. Matching off-pieces vary by class. Repeat after weekly resets for random drops; the armor set's visual checklist, not just its set-bonus count, is the goal.\n\n6. Permanently learn the final appearances. A trade/refund timer can delay credit. If all slots are learned but the achievement has not refreshed, relog; comments also report applying the complete set as a transmog refreshes credit. Do not buy or delete duplicate items before checking the actual missing slot.",
        stepCount = 6,
        waypoints = {
