    [18721] = {
        achievementId = 18721,
        name = "Outland Master of All",
        category = "Professions",
        sourceType = "Achievement",
        source = "Outland Master of All",
        acquisition = "Difficulty: Hard - Max all eleven primary Outland professions across profession characters, requiring substantial materials and preparation.\n\n1. Open this achievement's progress and check the OUTLAND skill bars already credited. The objective is all eleven primary professions, using your account's profession characters.\n\n2. Train the OUTLAND tier separately. Hellfire's Honor Hold and Thrallmar have trainers for most professions; ask a guard for your profession's location. For Inscription, use Recorder Lidio on Shattrath's Aldor Rise (36.2, 44.6) or Scribe Lanloer on Scryer's Tier (56.6, 74.6). For Engineering, use Technician Mihila on Aldor Rise (37.6, 31.6) or Engineer Sinbei on Scryer's Tier (43.6, 65.0). Choose the Shattrath side that is friendly to you. Cooking, Fishing and Archaeology do not replace a primary profession.\n\n3. Skinning option: train with Jelena Nightsky at Honor Hold (54.4, 63.2) or Moorutu at Thrallmar (56.2, 38.6). In OUTLAND Nagrand, kill and fully loot the clefthoofs and talbuks in the grasslands between Garadar, Halaa and Oshu'gun, then skin their corpses. Continue until OUTLAND Skinning is 75. A corpse with somebody's loot still on it cannot be skinned; move through the herds rather than waiting on one spawn.\n\n4. Herbalism / Mining options: train with Rorelien (53.6, 65.8) or Ruak Stronghorn (52.2, 36.2) for Herbalism, and Hurnak Grimmord (56.6, 63.8) or Krugosh (55.4, 37.6) for Mining. Enable the appropriate minimap tracking. Circle Hellfire's open ground for Felweed and Dreaming Glory and its cliffs for Fel Iron. If the easy nodes stop giving skill, move to Nagrand or Blade's Edge for higher Outland herbs and Adamantite. Gather the nodes yourself until the relevant bar is 75; buying herbs/ore does not level gathering.\n\n5. Crafting option: select OUTLAND recipes and inspect their actual skill color before making a batch. Engineering starts with Fel Iron Bolts, Fel Iron Casings and Elemental Blasting Powder, which feed later bombs/grenades. Tailoring uses Netherweave Cloth for bolts, bags and Netherweave armor. Leatherworking uses Knothide Leather for armor kits and Draenic/Felscale armor. Keep useful intermediate materials instead of selling everything between stages; return to the trainer when the current recipe turns green or grey.\n\n6. For the other crafting bars, use Alchemy's Outland elixirs/potions, Blacksmithing's Fel Iron armor and later Adamantite recipes, Enchanting's Arcane Dust / Planar Essence enchants, Jewelcrafting's Outland gem cuts and Adamantite jewelry, or Inscription's Ethereal Ink / Darkflame Ink recipes. Check the Unlearned recipe's source and required skill before buying reagents: some later recipes are vendor, reputation or dungeon drops. A recipe grey below 75 cannot finish the bar, even if its materials came from Outland.\n\n7. Raise each required Outland bar to 75 and recheck its criterion. For Outland Master of All the full list is Alchemy, Blacksmithing, Enchanting, Engineering, Herbalism, Inscription, Jewelcrafting, Leatherworking, Mining, Skinning and Tailoring. Use profession alts for that account-wide list instead of deleting a developed profession to rotate through eleven skills. If you only need one or two bars, follow the options for those chosen professions and skip the others.",
        stepCount = 7,
        waypoints = {
            { mapID = 100, x = 0.545, y = 0.647, step = 2, label = "Alliance: Honor Hold - profession trainer hub" },
            { mapID = 100, x = 0.542, y = 0.385, step = 2, label = "Horde: Thrallmar - profession trainer hub" },
            {
                mapID = 111,
                x = 0.36200000000000004,
                y = 0.446,
                step = 2,
                label = "Aldor: Recorder Lidio - Outland Inscription",
            },
            {
                mapID = 111,
                x = 0.5660000000000001,
                y = 0.746,
                step = 2,
                label = "Scryers: Scribe Lanloer - Outland Inscription",
            },
            { mapID = 111, x = 0.376, y = 0.316, step = 2, label = "Aldor: Technician Mihila - Outland Engineering" },
            { mapID = 111, x = 0.436, y = 0.65, step = 2, label = "Scryers: Engineer Sinbei - Outland Engineering" },
            { mapID = 100, x = 0.544, y = 0.632, step = 3, label = "Alliance: Jelena Nightsky - Outland Skinning" },
            { mapID = 100, x = 0.562, y = 0.386, step = 3, label = "Horde: Moorutu - Outland Skinning" },
            { mapID = 107, x = 0.5, y = 0.5, step = 3, label = "Nagrand grasslands - clefthoof / talbuk skinning circuit" },
            { mapID = 100, x = 0.536, y = 0.6579999999999999, step = 4, label = "Alliance: Rorelien - Outland Herbalism" },
            { mapID = 100, x = 0.522, y = 0.36200000000000004, step = 4, label = "Horde: Ruak Stronghorn - Outland Herbalism" },
            { mapID = 100, x = 0.5660000000000001, y = 0.638, step = 4, label = "Alliance: Hurnak Grimmord - Outland Mining" },
            { mapID = 100, x = 0.5539999999999999, y = 0.376, step = 4, label = "Horde: Krugosh - Outland Mining" },
            { mapID = 100, x = 0.3, y = 0.6, step = 4, label = "Western Hellfire - herb / Fel Iron search area" },
            { mapID = 107, x = 0.5, y = 0.5, step = 4, label = "Nagrand - herb / Adamantite search circuit" },
            { mapID = 105, x = 0.52, y = 0.6, step = 4, label = "Blade's Edge - alternative higher-node circuit" },
        },
        tips = "Gathering pins mark broad circuits, not guaranteed active nodes. Recipe skill colors and requirements in the current profession window take priority over comments written before the expansion skill split.",
        sources = {
            "https://www.wowhead.com/achievement=18721#comments",
