    [62460] = {
        achievementId = 62460,
        name = "Family Battler of Outland",
        category = "Pet Battles",
        sourceType = "Achievement",
        source = "Family Battler of Outland",
        acquisition = "Difficulty: Hard - Prepare teams for all ten pet families and complete every family restriction against all five tamers.\n\n1. Unlock the Outland trainer battles through the pet-tamer quest progression if the trainers will not offer a battle. Prepare level-25 teams for all ten families; this meta needs ten separate family achievements, not one mixed-family team.\n\n2. Defeat Nicki Tinytech in Hellfire Peninsula with each missing family team. Track the child achievements so you know which family victories still need credit.\n\n3. At Ras'an in Zangarmarsh, repeat the wins for each family when his battle is available. A level-24 carry pet or an off-family counterpet makes that attempt ineligible.\n\n4. Continue the family victories at Narrok in Outland Nagrand.\n\n5. Continue at Morulu the Elder in Shattrath. Heal the team between attempts and respect each trainer's daily availability.\n\n6. Finish the family victories against Bloodknight Antari in Outland Shadowmoon Valley. The old Gorma Asaan reference was corrected to Antari; do not search another continent for that NPC. Complete Aquatic, Beast, Critter, Dragonkin, Elemental, Flying, Humanoid, Magic, Mechanical and Undead Battler of Outland to finish the meta.",
        stepCount = 6,
        waypoints = {
            { mapID = 100, x = 0.644, y = 0.49200000000000005, step = 2, label = "Nicki Tinytech - Mechanical opponents" },
            { mapID = 102, x = 0.172, y = 0.506, step = 3, label = "Ras'an - Humanoid, Flying, Magic" },
            { mapID = 107, x = 0.61, y = 0.494, step = 4, label = "Narrok - Critter, Aquatic, Beast" },
            { mapID = 111, x = 0.59, y = 0.706, step = 5, label = "Morulu the Elder - Aquatic opponents" },
            { mapID = 104, x = 0.306, y = 0.418, step = 6, label = "Bloodknight Antari - Magic, Elemental, Dragonkin" },
        },
        wowheadUrl = "https://www.wowhead.com/achievement=62460",
        sourceURL = "https://www.wowhead.com/achievement=62460#comments",
        difficultyReason = "Prepare teams for all ten pet families and complete every family restriction against all five tamers.",
        difficulty = "hard",
    },
    [62466] = {
        achievementId = 62466,
        name = "Aquatic Battler of Outland",
        category = "Pet Battles",
        sourceType = "Achievement",
        source = "Aquatic Battler of Outland",
        acquisition = "Difficulty: Medium - Prepare three level-25 pets of the required family and defeat all five tamers with eligible teams.\n\n1. Prepare THREE level-25 Aquatic pets. Every slot must satisfy the family and level requirement, even if one pet never fights. A reported starting team is Storm-infused Snapdragon (1/1/2), Hermit Crab (1/1/2) and Snarly (1/1/2). The numbers select the first/second ability in each of the three Journal ability slots; heal between battles.\n\n2. Defeat Nicki Tinytech in Hellfire Peninsula (64.4, 49.2). Her opponents are Mechanical. Keep your entire team in the required family; a pet's attack type can differ from its family.\n\n3. Defeat Ras'an beside Sporeggar in Zangarmarsh (17.2, 50.6). His opponents are Humanoid, Flying and Magic. Reorder your eligible team and change abilities before the fight to cover these matchups.\n\n4. Defeat Narrok in Nagrand, OUTLAND (61.0, 49.4). His opponents are Critter, Aquatic and Beast. Heal and revive before moving to the next trainer.\n\n5. Defeat Morulu the Elder in Shattrath's Lower City (59.0, 70.6). All three enemies are Aquatic crocolisks; check their queued attacks before spending a defensive cooldown.\n\n6. Defeat Bloodknight Antari in Shadowmoon Valley, OUTLAND (30.6, 41.8). His enemies are Magic, Elemental and Dragonkin. Antari replaced the old erroneous Gorma Asaan criterion. Check that all five trainer criteria have credited; daily availability can prevent immediately repeating an already completed tamer.\n\n7. Against Flying enemies, an Aquatic pet with Magic attacks, such as Emerald Turtle, can help.",
        stepCount = 7,
        waypoints = {
            { mapID = 100, x = 0.644, y = 0.49200000000000005, step = 2, label = "Nicki Tinytech - Mechanical opponents" },
            { mapID = 102, x = 0.172, y = 0.506, step = 3, label = "Ras'an - Humanoid, Flying, Magic" },
            { mapID = 107, x = 0.61, y = 0.494, step = 4, label = "Narrok - Critter, Aquatic, Beast" },
            { mapID = 111, x = 0.59, y = 0.706, step = 5, label = "Morulu the Elder - Aquatic opponents" },
            { mapID = 104, x = 0.306, y = 0.418, step = 6, label = "Bloodknight Antari - Magic, Elemental, Dragonkin" },
        },
        tips = "These are player-reported teams, not guaranteed turn-by-turn solutions. Breed, speed, critical hits and random sleeps can require a retry or a different eligible pet.",
        sources = {
            "https://www.wowhead.com/achievement=62466#comments:id=6412634",
            "https://www.wowhead.com/achievement=62460#comments:id=6397806",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=62466",
        sourceURL = "https://www.wowhead.com/achievement=62466#comments",
        difficultyReason = "Prepare three level-25 pets of the required family and defeat all five tamers with eligible teams.",
        difficulty = "medium",
    },
